#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/wait.h>
#include <sys/types.h>
#include <sys/ipc.h>
#include <sys/sem.h>

union semun { int val; struct semid_ds *buf; unsigned short *array; };

int P(int id, int n) { struct sembuf o = {(unsigned short) n, -1, 0}; return semop(id, &o, 1); }
int V(int id, int n) { struct sembuf o = {(unsigned short) n, +1, 0}; return semop(id, &o, 1); }

int main(void) {
    int semid = semget(IPC_PRIVATE, 2, IPC_CREAT | 0600);
    if (semid == -1) { perror("semget"); exit(EXIT_FAILURE); }

    union semun arg;
    unsigned short vals[2] = {0, 0};
    arg.array = vals;
    semctl(semid, 0, SETALL, arg);

    pid_t pid = fork();
    if (pid == -1) { perror("fork"); exit(EXIT_FAILURE); }

    if (pid == 0) {
        P(semid, 0);
        printf("fils : travail\n");
        fflush(stdout);
        V(semid, 1);
        exit(EXIT_SUCCESS);
    }

    printf("pere : demarrage\n");
    fflush(stdout);
    V(semid, 0);
    P(semid, 1);
    wait(NULL);
    printf("pere : termine\n");
    fflush(stdout);

    semctl(semid, 0, IPC_RMID);
    return 0;
}

#include <stdio.h>
