#include <sys/ipc.h>
#include <sys/msg.h>

struct message { long mtype; char texte[32]; };

int main(void) {
    int msqid = msgget(IPC_PRIVATE, IPC_CREAT | 0600);
    if (msqid == -1) { perror("msgget"); exit(EXIT_FAILURE); }

    struct message m;
    long types[3] = {3, 1, 2};
    const char *corps[3] = {"log", "urgent", "normal"};
    for (int i = 0; i < 3; i++) {
        m.mtype = types[i];
        strcpy(m.texte, corps[i]);
        msgsnd(msqid, &m, sizeof(m.texte), 0);
    }

    struct message r;
    msgrcv(msqid, &r, sizeof(r.texte), 2, 0);
    printf("msgtyp=2  -> %s\n", r.texte);

    msgrcv(msqid, &r, sizeof(r.texte), -2, 0);
    printf("msgtyp=-2 -> %s\n", r.texte);

    msgrcv(msqid, &r, sizeof(r.texte), 0, 0);
    printf("msgtyp=0  -> %s\n", r.texte);

    msgctl(msqid, IPC_RMID, NULL);
    return 0;
}

