#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/wait.h>
#include <sys/types.h>
#include <sys/ipc.h>
#include <sys/shm.h>

int main(void) {
    int shmid = shmget(IPC_PRIVATE, sizeof(int), IPC_CREAT | 0600);
    if (shmid == -1) { perror("shmget"); exit(EXIT_FAILURE); }

    pid_t pid = fork();
    if (pid == -1) { perror("fork"); exit(EXIT_FAILURE); }

    if (pid == 0) {
        int *p = (int *) shmat(shmid, NULL, 0);
        if (p == (void *) -1) { perror("shmat"); exit(EXIT_FAILURE); }
        *p = 1234;
        shmdt(p);
        exit(EXIT_SUCCESS);
    }

    wait(NULL);
    int *p = (int *) shmat(shmid, NULL, 0);
    if (p == (void *) -1) { perror("shmat"); exit(EXIT_FAILURE); }
    printf("valeur lue : %d\n", *p);
    shmdt(p);
    shmctl(shmid, IPC_RMID, NULL);
    return 0;
}

